  'bib.mapa.tecnicos': T(['{n} pregunta no se pudo mostrar en el modelo y no contó.', '{n} preguntas no se pudieron mostrar en el modelo y no contaron.'], ['{n} question could not be shown on the model and did not count.', '{n} questions could not be shown on the model and did not count.'], ['{n} Frage konnte am Modell nicht gezeigt werden und zählte nicht.', '{n} Fragen konnten am Modell nicht gezeigt werden und zählten nicht.'], ['{n} question n’a pas pu être affichée sur le modèle et n’a pas compté.', '{n} questions n’ont pas pu être affichées sur le modèle et n’ont pas compté.'], ['{n} domanda non si è potuta mostrare sul modello e non è stata contata.', '{n} domande non si sono potute mostrare sul modello e non sono state contate.']),
  'bib.mapa.investigacion': T('Repasar recordando, espaciado en el tiempo, tiene apoyo en la investigación sobre el aprendizaje de la anatomía; su efecto concreto en Anato3D todavía no se ha medido.', 'Reviewing by recalling, spaced over time, is supported by research on learning anatomy; its specific effect in Anato3D has not been measured yet.', 'Wiederholen durch Abrufen, zeitlich verteilt, wird von der Forschung zum Anatomielernen gestützt; seine konkrete Wirkung in Anato3D wurde noch nicht gemessen.', 'Réviser en se remémorant, de façon espacée dans le temps, est soutenu par la recherche sur l’apprentissage de l’anatomie ; son effet concret dans Anato3D n’a pas encore été mesuré.', 'Ripassare richiamando alla memoria, a intervalli nel tempo, è sostenuto dalla ricerca sull’apprendimento dell’anatomia; il suo effetto concreto in Anato3D non è ancora stato misurato.'),
  'bib.mapa.estudio': T('Ver un estudio', 'See a study', 'Eine Studie ansehen', 'Voir une étude', 'Vedi uno studio'),
  'bib.motivo.confusion.hoy': T('Volvemos a practicar esto porque hoy lo confundiste con «{x}».', 'We are practicing this again because today you confused it with “{x}”.', 'Wir üben das noch einmal, weil du es heute mit „{x}“ verwechselt hast.', 'Nous le retravaillons parce qu’aujourd’hui vous l’avez confondu avec « {x} ».', 'Lo ripassiamo perché oggi l’hai confuso con «{x}».'),
  'bib.motivo.confusion.ayer': T('Volvemos a practicar esto porque ayer lo confundiste con «{x}».', 'We are practicing this again because yesterday you confused it with “{x}”.', 'Wir üben das noch einmal, weil du es gestern mit „{x}“ verwechselt hast.', 'Nous le retravaillons parce qu’hier vous l’avez confondu avec « {x} ».', 'Lo ripassiamo perché ieri l’hai confuso con «{x}».'),
  'bib.motivo.confusion.dia': T('Volvemos a practicar esto porque el {fecha} lo confundiste con «{x}».', 'We are practicing this again because on {fecha} you confused it with “{x}”.', 'Wir üben das noch einmal, weil du es am {fecha} mit „{x}“ verwechselt hast.', 'Nous le retravaillons parce que le {fecha} vous l’avez confondu avec « {x} ».', 'Lo ripassiamo perché il {fecha} l’hai confuso con «{x}».'),
  'bib.motivo.eleccion.hoy': T('Volvemos a practicar esto porque hoy respondiste «{x}», que no era la respuesta.', 'We are practicing this again because today you answered “{x}”, which was not the answer.', 'Wir üben das noch einmal, weil du heute „{x}“ geantwortet hast, was nicht stimmte.', 'Nous le retravaillons parce qu’aujourd’hui vous avez répondu « {x} », qui n’était pas la réponse.', 'Lo ripassiamo perché oggi hai risposto «{x}», che non era la risposta.'),
  'bib.motivo.eleccion.ayer': T('Volvemos a practicar esto porque ayer respondiste «{x}», que no era la respuesta.', 'We are practicing this again because yesterday you answered “{x}”, which was not the answer.', 'Wir üben das noch einmal, weil du gestern „{x}“ geantwortet hast, was nicht stimmte.', 'Nous le retravaillons parce qu’hier vous avez répondu « {x} », qui n’était pas la réponse.', 'Lo ripassiamo perché ieri hai risposto «{x}», che non era la risposta.'),
  'bib.motivo.eleccion.dia': T('Volvemos a practicar esto porque el {fecha} respondiste «{x}», que no era la respuesta.', 'We are practicing this again because on {fecha} you answered “{x}”, which was not the answer.', 'Wir üben das noch einmal, weil du am {fecha} „{x}“ geantwortet hast, was nicht stimmte.', 'Nous le retravaillons parce que le {fecha} vous avez répondu « {x} », qui n’était pas la réponse.', 'Lo ripassiamo perché il {fecha} hai risposto «{x}», che non era la risposta.'),
  'bib.motivo.nolose.hoy': T('Volvemos a practicar esto porque hoy marcaste «No lo sé».', 'We are practicing this again because today you chose “I don’t know”.', 'Wir üben das noch einmal, weil du heute „Weiß ich nicht“ gewählt hast.', 'Nous le retravaillons parce qu’aujourd’hui vous avez choisi « Je ne sais pas ».', 'Lo ripassiamo perché oggi hai scelto «Non lo so».'),
  'bib.motivo.nolose.ayer': T('Volvemos a practicar esto porque ayer marcaste «No lo sé».', 'We are practicing this again because yesterday you chose “I don’t know”.', 'Wir üben das noch einmal, weil du gestern „Weiß ich nicht“ gewählt hast.', 'Nous le retravaillons parce qu’hier vous avez choisi « Je ne sais pas ».', 'Lo ripassiamo perché ieri hai scelto «Non lo so».'),
  'bib.motivo.nolose.dia': T('Volvemos a practicar esto porque el {fecha} marcaste «No lo sé».', 'We are practicing this again because on {fecha} you chose “I don’t know”.', 'Wir üben das noch einmal, weil du am {fecha} „Weiß ich nicht“ gewählt hast.', 'Nous le retravaillons parce que le {fecha} vous avez choisi « Je ne sais pas ».', 'Lo ripassiamo perché il {fecha} hai scelto «Non lo so».'),
  'bib.motivo.fallo.hoy': T('Volvemos a practicar esto porque hoy lo fallaste.', 'We are practicing this again because today you got it wrong.', 'Wir üben das noch einmal, weil du es heute falsch hattest.', 'Nous le retravaillons parce qu’aujourd’hui vous l’avez raté.', 'Lo ripassiamo perché oggi l’hai sbagliato.'),
  'bib.motivo.fallo.ayer': T('Volvemos a practicar esto porque ayer lo fallaste.', 'We are practicing this again because yesterday you got it wrong.', 'Wir üben das noch einmal, weil du es gestern falsch hattest.', 'Nous le retravaillons parce qu’hier vous l’avez raté.', 'Lo ripassiamo perché ieri l’hai sbagliato.'),
  'bib.motivo.fallo.dia': T('Volvemos a practicar esto porque el {fecha} lo fallaste.', 'We are practicing this again because on {fecha} you got it wrong.', 'Wir üben das noch einmal, weil du es am {fecha} falsch hattest.', 'Nous le retravaillons parce que le {fecha} vous l’avez raté.', 'Lo ripassiamo perché il {fecha} l’hai sbagliato.'),
  'bib.esperanRecientes': T('Lo que acabas de fallar vuelve dentro de un rato: repetirlo ya solo serviría para memorizar la opción. Mientras, repasa la lección o practica otra cosa.', 'What you just got wrong comes back in a while: repeating it now would only help you memorize the option. Meanwhile, review the lesson or practice something else.', 'Was du gerade falsch hattest, kommt bald wieder: Es sofort zu wiederholen, würde nur helfen, die Antwort auswendig zu lernen. Lies inzwischen die Lektion noch einmal oder übe etwas anderes.', 'Ce que vous venez de rater reviendra dans un moment : le répéter tout de suite ne servirait qu’à mémoriser l’option. En attendant, relisez la leçon ou pratiquez autre chose.', 'Quello che hai appena sbagliato torna tra un po’: ripeterlo subito servirebbe solo a memorizzare l’opzione. Nel frattempo, rivedi la lezione o esercitati su altro.'),
  'bib.nadaQueRepasar': T('Todavía no hay preguntas que repasar aquí.', 'There are no questions to review here yet.', 'Hier gibt es noch keine Fragen zu wiederholen.', 'Il n’y a pas encore de questions à revoir ici.', 'Qui non ci sono ancora domande da ripassare.'),
